new:
if method != "initialize"
    && !request
        .headers
        .get("mcp-protocol-version")
        .is_some_and(|version| protocol_version_is_supported(version))
{
    return write_http_response(
        &mut stream,
        400,
        "text/plain",
        b"missing or unsupported MCP-Protocol-Version",
    );
}
